"""Freeze Stage 3C predictor coding and model protocol before fitting."""
import json,hashlib,sys,platform,subprocess
from pathlib import Path
from datetime import datetime,timezone
import pandas as pd,numpy as np
ROOT=Path(__file__).resolve().parents[1];E=ROOT/'docs/stage3c_evidence';M=ROOT/'models/stage3c';F=ROOT/'docs/stage3c_figures'
def now():return datetime.now(timezone.utc).isoformat()
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def read(p):return json.loads(p.read_text())
def save(n,v): (E/n).write_text(json.dumps(v,indent=2,allow_nan=False)+'\n')
def panel(kind):
 receipt=read(ROOT/'docs/stage3b_evidence/panel_release_receipt.json')['panels']['replication' if kind=='primary' else 'full'];p=ROOT/receipt['path'];assert sha(p)==receipt['sha256'];return pd.read_parquet(p),receipt
INTERPRETATION='This analysis estimates associations within NBA players with available combine measurements. It does not identify a causal effect of arm length on shooting, because combine participation, NBA selection, role assignment, persistent player differences, shooting opportunity and other factors may jointly affect the observed sample.'
def setup():
 assert not (E/'model_protocol.json').exists()
 auth=read(ROOT/'docs/stage3b_evidence/part_b_authorization.json');assert auth['part_b_authorized'] is True
 assert sha(ROOT/'docs/stage3b_evidence/amended_gate_decision.json')==auth['gate_sha256'];assert sha(ROOT/'docs/stage3b_evidence/panel_release_receipt.json')==auth['release_receipt_sha256']
 prior={str(p.relative_to(ROOT)):sha(p) for p in ROOT.rglob('*') if p.is_file() and not any(x.startswith('.venv') or x in {'__pycache__','.git'} for x in p.parts) and 'stage3c' not in str(p.relative_to(ROOT))};save('prior_preservation_manifest.json',prior)
 d,receipt=panel('primary');assert (d.season.nunique(),len(d),d.player_id.nunique(),d.fta.sum())==(13,4117,857,469099);assert '2013-14' not in set(d.season)
 g=read(ROOT/'docs/stage1_evidence/residualization_model.json');assert g['intercept']==4.574910520685837 and g['slope']==1.0013410045156863
 np.testing.assert_array_equal(d.residual_wingspan,d.wingspan_inches-(g['intercept']+g['slope']*d.height_wo_shoes_inches))
 u=d.drop_duplicates('player_id');center=float(u.height_wo_shoes_inches.mean());positions=sorted(d.combine_position.fillna('unknown').replace('','unknown').unique());seasons=sorted(d.season.unique());ids=sorted(d.player_id.unique(),key=int)
 for v in ['height_wo_shoes_inches','wingspan_inches','residual_wingspan','combine_position','combine_year']:assert d.groupby('player_id')[v].nunique().max()==1
 assert (d.combine_year<=d.first_observed_season.str[:4].astype(int)).all()
 pd.DataFrame({'player_index':range(len(ids)),'player_id':ids}).to_csv(E/'primary_player_index.csv',index=False)
 pip=subprocess.run([sys.executable,'-m','pip','freeze'],capture_output=True,text=True,check=True);(ROOT/'requirements-stage3c.txt').write_text(pip.stdout)
 check=subprocess.run([sys.executable,'-m','pip','check'],capture_output=True,text=True);(E/'pip_check.txt').write_text(check.stdout+check.stderr);assert check.returncode==0
 from importlib.metadata import version
 env=dict(python=platform.python_version(),executable=sys.executable,platform=platform.platform(),packages={x:version(x) for x in ['pymc','arviz','numpy','scipy','pandas','pyarrow','matplotlib','pytensor']},requirements_sha256=sha(ROOT/'requirements-stage3c.txt'));save('environment.json',env)
 protocol=dict(frozen_at=now(),primary_panel_sha256=receipt['sha256'],response='FTM out of FTA',likelihood='BetaBinomial(n=FTA, alpha=mu*kappa, beta=(1-mu)*kappa)',predictors=['residual_wingspan','centered_height','original_combine_position','season','player_random_intercept'],residualization=dict(intercept=g['intercept'],slope=g['slope'],refitted=False),height_center=center,height_center_rule='mean across unique players in primary accounting panel',residual_scale='raw inches, no centering',position_levels=positions,position_reference='C',season_levels=seasons,season_reference=seasons[0],coding='reference indicators; full panel adds 2013-14 indicator, same primary height center and priors',random_effect='z_player ~ Normal(0,1); u_player=sigma_player*z_player; deterministic numeric-ID indexing includes zero-attempt-only players',priors=dict(beta_0=['Normal',0,2.5],beta_RW=['Normal',0,.5],beta_H=['Normal',0,.5],position_effect=['Normal',0,1],season_effect=['Normal',0,1],sigma_player=['HalfNormal',1],log_kappa=['Normal',3,2]),transforms=dict(kappa='exp(log_kappa)',rho='1/(1+kappa)'),sampling=dict(chains=4,tune=2000,draws=2000,target_accept=.95,seed=20260928,sampler='PyMC NUTS',cores=4,blas_cores=1),recovery=dict(max_runs=1,tune=4000,draws=4000,target_accept=.99,trigger='generic diagnostics only; no scientific posterior inspection before pass',unchanged=['formula','exposure','priors','covariates']),diagnostics=dict(max_rhat=1.01,min_bulk_ess=400,min_tail_ess=400,min_bfmi=.3,max_divergences=0,max_treedepth_hits=0,covariance_finite=True,visual_chain_review_required=True,key_parameters='all fixed coefficients including every position/season; sigma_player, log_kappa, kappa, rho'),prior_predictive=dict(draws=1000,seed=20260928,stop_if='nonfinite mu, or more than 25% mu below .01, or more than 25% mu above .99; broad remaining support documented',outcomes_not_examined=True),credible_interval='95% equal-tail (2.5th,97.5th percentiles)',contrast=dict(quantiles='Q25/Q75 across all primary accounting player-seasons, unweighted, linear interpolation',averaging='equal weights over positive-FTA player-seasons',primary='retain fitted player random intercept per posterior draw',secondary='set u=0; reference-player contrast, NOT marginalized over random-effect distribution'),PPC=dict(draws=1000,seed=20260929,method='Beta draw then Binomial for each observed positive-FTA row, retaining fitted player effects',strata=['1-9','10-49','50-99','100-299','300+'],metrics=['pooled rate','FT-rate SD, q05, q50, q95, zero/one fraction','FTA-stratum rate distribution','season pooled rates','SD of player pooled rates','mean within-player repeated-season rate SD'],serious_failure_rule='pooled rate outside 99% predictive interval OR at least 3 of global rate SD/q05/q50/q95/zero fraction/one fraction outside 99% intervals OR at least one-third of season pooled rates outside 99%; additional visual review before release'),primary_freeze_before_full=True,stage3d_authorized=False,interpretation=INTERPRETATION,minute_limitation=auth['mandatory_limitation'],reproduction='exact numerical summaries from saved trace; seeded refits compared within Monte Carlo uncertainty, not byte-identical traces',scientific_sign_is_not_execution_gate=True)
 save('model_protocol.json',protocol);save('protocol_freeze_receipt.json',dict(frozen_at=protocol['frozen_at'],sha256=sha(E/'model_protocol.json')))
 save('primary_panel_model_data_summary.json',dict(seasons=13,player_seasons=len(d),unique_players=len(ids),FTA=int(d.fta.sum()),positive_FTA_rows=int((d.fta>0).sum()),zero_FTA_rows=int((d.fta==0).sum()),zero_attempt_only_players=int((d.groupby('player_id').fta.sum()==0).sum()),height_center=center,panel_sha256=receipt['sha256']))
 print(json.dumps(read(E/'primary_panel_model_data_summary.json'),indent=2))
if __name__=='__main__':setup()
